let
    源 = Odbc.Query("dsn=bytehouse_rl", "-- ========================================#(lf)-- SQL: 本期日期维度数据#(lf)-- 用途: Power BI 日期表加载，用于""本期""筛选器#(lf)-- 表: indep_rl_ads.a05_e2e_paid_media_channel_data#(lf)-- 说明: #(lf)--   - dt 和 data_date 转为 DATE 类型#(lf)--   - etl_time 保持原始 STRING 保留时间部分#(lf)--   - 提取完整的日期维度字段#(lf)-- ========================================#(lf)#(lf)SELECT DISTINCT#(lf)    etl_time                                    AS `数据更新时间`,#(lf)    STR_TO_DATE(dt, '%Y-%m-%d')                   AS `分区字段_数据快照日期`,#(lf)    data_type                                   AS `数据类型`,#(lf)    STR_TO_DATE(data_date, '%Y-%m-%d')            AS `数据日期`,#(lf)    data_week                                   AS `数据周`,#(lf)    data_week_name                              AS `数据周名称`,#(lf)    data_month                                  AS `数据月份`,#(lf)    data_month_name                             AS `数据月份名称`,#(lf)    data_quarter                                AS `数据季度`,#(lf)    data_quarter_name                           AS `数据季度名称`,#(lf)    data_year                                   AS `数据年份`,#(lf)    data_year_name                              AS `数据年份名称`#(lf)FROM indep_rl_ads.a05_e2e_paid_media_channel_data_d#(lf)WHERE data_type = 'day'#(lf)ORDER BY STR_TO_DATE(data_date, '%Y-%m-%d');"),
    筛选的行 = Table.SelectRows(源, each ([数据日期] <> null))
in
    筛选的行